import unittest
from unittest.mock import patch, MagicMock
from datetime import datetime

class TestLogging(unittest.TestCase):

    @patch('logging_system.store_event_log')
    def test_store_event_log_in_non_volatile_memory(self, mock_store_event_log):
        # Test that the event log is stored in non-volatile memory
        logging_system = LoggingSystem()
        logging_system.log_event("Test Event")
        mock_store_event_log.assert_called_once()

    @patch('logging_system.store_event_log')
    def test_event_log_includes_ventilation_settings(self, mock_store_event_log):
        # Test that the event log includes all confirmed ventilation settings
        logging_system = LoggingSystem()
        ventilation_settings = {"fan_speed": "high", "temperature": "22C"}
        logging_system.log_ventilation_settings(ventilation_settings)
        mock_store_event_log.assert_called_with(ventilation_settings)

    @patch('logging_system.store_event_log')
    @patch('datetime.datetime')
    def test_event_log_includes_date_and_timestamp(self, mock_datetime, mock_store_event_log):
        # Test that the event log includes a date and timestamp
        mock_datetime.now.return_value = datetime(2023, 10, 5, 14, 30, 0)
        logging_system = LoggingSystem()
        logging_system.log_event("Test Event")
        mock_store_event_log.assert_called_with("Test Event", "2023-10-05 14:30:00")

    @patch('logging_system.store_event_log')
    @patch('datetime.datetime')
    def test_event_log_includes_rtc_changes(self, mock_datetime, mock_store_event_log):
        # Test that the event log includes changes to the system's real time clock
        mock_datetime.now.return_value = datetime(2023, 10, 5, 14, 30, 0)
        logging_system = LoggingSystem()
        logging_system.log_rtc_change("2023-10-05 14:30:00", "2023-10-05 15:00:00")
        mock_store_event_log.assert_called_with("RTC Change: 2023-10-05 14:30:00 -> 2023-10-05 15:00:00")

